393	/// If the value is content, the string "element" and the name of its element
394	/// function, or the string "type" and the name of the value's type.
395	fn element_or_type_with_name(value: &Value) -> (&'static str, &'static str) {
396	    if let Value::Content(content) = value {
397	        ("element", content.elem().name())
398	    } else {
399	        ("type", value.ty().long_name())
400	    }
401	}
