403	impl Eval for ast::Args<'_> {
404	    type Output = Args;
405	
406	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
407	        let mut items = EcoVec::with_capacity(self.items().count());
408	
409	        for arg in self.items() {
410	            let span = arg.span();
411	            match arg {
412	                ast::Arg::Pos(expr) => {
413	                    items.push(Arg {
414	                        span,
415	                        name: None,
416	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
417	                    });
418	                }
419	                ast::Arg::Named(named) => {
420	                    let expr = named.expr();
421	                    items.push(Arg {
422	                        span,
423	                        name: Some(named.name().get().clone().into()),
424	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
425	                    });
426	                }
427	                ast::Arg::Spread(spread) => match spread.expr().eval(vm)? {
428	                    Value::None => {}
429	                    Value::Array(array) => {
430	                        items.extend(array.into_iter().map(|value| Arg {
431	                            span,
432	                            name: None,
433	                            value: Spanned::new(value, span),
434	                        }));
435	                    }
436	                    Value::Dict(dict) => {
437	                        items.extend(dict.into_iter().map(|(key, value)| Arg {
438	                            span,
439	                            name: Some(key),
440	                            value: Spanned::new(value, span),
441	                        }));
442	                    }
443	                    Value::Args(args) => items.extend(args.items),
444	                    v => bail!(spread.span(), "cannot spread {}", v.ty()),
445	                },
446	            }
447	        }
448	
449	        // We do *not* use the `self.span()` here because we want the callsite
450	        // span to be one level higher (the whole function call).
451	        Ok(Args { span: Span::detached(), items })
452	    }
453	}
