/// Call the function with the given context and arguments.
pub fn call<A: IntoArgs>(
    &self,
    engine: &mut Engine,
    context: Tracked<Context>,
    args: A,
) -> SourceResult<Value> {
    self.call_impl(engine, context, args.into_args(self.span))
